package com.moonsworth.lunar.client.cosmetics.gecko;

public class ModelVertexShader {
   public ModelVertexShader() {
   }

   public static String method1() {
      return "#version 430\n\nlayout (local_size_x = 32) in;\n\nstruct InputData {\n    float x;\n    float y;\n    float z;\n    uint color;\n    float u;\n    float v;\n    uint lightmap;\n    uint overlay;\n    uint normals;\n};\n\nlayout(binding = 0, std430) readonly buffer SrcBuffer {\n    InputData[] inputData;\n};\n\nstruct OutputData {\n    float x;\n    float y;\n    float z;\n    float u;\n    float v;\n};\n\nlayout(binding = 1, std430) writeonly buffer DstBuffer {\n    OutputData[] outputData;\n};\n\nlayout(std140, binding = 2) uniform Context {\n    mat3 normalTransform;\n    int lightMap;\n    int srcLength;\n};\n\nvoid main() {\n    if (gl_GlobalInvocationID.x >= srcLength) {\n        return;\n    }\n\n    InputData ip = inputData[gl_GlobalInvocationID.x];\n    outputData[gl_GlobalInvocationID.x] = OutputData(ip.x, ip.y, ip.z, ip.u, ip.v);\n}\n";
   }

   public static String method2() {
      return "#version 430\n\nstruct Transform {\n    // translate\n    float tX;\n    float tY;\n    float tZ;\n    // scale\n    float sX;\n    float sY;\n    float sZ;\n    // quaternion\n    float qX;\n    float qY;\n    float qZ;\n    float qW;\n};\n\nstruct VertexDataIn {\n    float vX;\n    float vY;\n    float vZ;\n    uint color;\n    float tX;\n    float tY;\n    uint overlay;\n    uint lightmap;\n    uint normal;\n    int transformIndex;\n};\n\nstruct VertexDataOut {\n    float vX;\n    float vY;\n    float vZ;\n    uint color;\n    float tX;\n    float tY;\n    uint overlay;\n    uint lightmap;\n    uint normal;\n};\n\nlayout(std430, binding = 0) readonly buffer BaseVertices {\n    VertexDataIn vertexData[];\n};\n\nlayout(std430, binding = 1) readonly buffer CurrentTransforms {\n    Transform currentTransforms[];\n};\n\nlayout(std430, binding = 2) writeonly buffer OutputVertices {\n    VertexDataOut vertexDataOut[];\n};\n\nmat4 quaternionToMat(vec4 quat) {\n    float w2 = quat.w * quat.w;\n    float x2 = quat.x * quat.x;\n    float y2 = quat.y * quat.y;\n    float z2 = quat.z * quat.z;\n    float zw = quat.z * quat.w;\n    float dzw = zw + zw;\n    float xy = quat.x * quat.y;\n    float dxy = xy + xy;\n    float xz = quat.x * quat.z;\n    float dxz = xz + xz;\n    float yw = quat.y * quat.w;\n    float dyw = yw + yw;\n    float yz = quat.y * quat.z;\n    float dyz = yz + yz;\n    float xw = quat.x * quat.w;\n    float dxw = xw + xw;\n    vec4 col1 = vec4(w2 + x2 - z2 - y2, dxy + dzw, dxz - dyw, 0.0);\n    vec4 col2 = vec4(-dzw + dxy, y2 - z2 + w2 - x2, dyz + dxw, 0.0);\n    vec4 col3 = vec4(dyw + dxz, dyz - dxw, z2 - y2 - x2 + w2, 0.0);\n    return mat4(col1, col2, col3, vec4(0.0, 0.0, 0.0, 1.0));\n}\n\nlayout(local_size_x = 32) in;\n\nlayout(std140, binding = 3) uniform Context {\n    mat3 normalTransform;\n    int lightMap;\n    int srcLength;\n    int tintColor;\n    int flippedWinding;\n    mat4 modelPose;\n};\n\nvoid main() {\n    uint id = gl_GlobalInvocationID.x;\n\n    if (id >= srcLength) {\n        return;\n    }\n\n    // flipped winding swaps vertex pairs within each quad: 0 1 2 3 -> 1 0 3 2\n    uint srcId = flippedWinding != 0 ? (id ^ 1u) : id;\n\n    VertexDataIn vertData = vertexData[srcId];\n\n    int transformIndex = vertData.transformIndex;\n\n    Transform cur = currentTransforms[transformIndex];\n\n    vec4 curQuat = vec4(cur.qX, cur.qY, cur.qZ, cur.qW);\n\n    vec3 scale = vec3(cur.sX, cur.sY, cur.sZ);\n    vec3 translate = vec3(cur.tX, cur.tY, cur.tZ);\n\n    mat4 transform = quaternionToMat(curQuat);\n\n    mat3 directionTransform = mat3(transform);\n\n    transform[0].xyz *= scale.x;\n    transform[1].xyz *= scale.y;\n    transform[2].xyz *= scale.z;\n    transform[3].xyz += translate;\n\n    vec3 normal = unpackSnorm4x8(vertData.normal).xyz;\n\n    // rotate and apply signum of scale components\n    vec3 transformedNormal = directionTransform * (normal * sign(sign(scale) + 0.5));\n    transformedNormal = normalTransform * transformedNormal;\n\n    uint flags = (vertData.normal >> 24u) & 255u;\n    // bvec3 negateFlags = bvec3(flags & 1u, flags & 2u, flags & 4u);\n    bvec3 lessMasks = lessThan(transformedNormal, vec3(0.0));\n\n    // vec3(lessMasks) * vec3(negateFlags) is basically a logical and\n    // negate the components so its either -1 or 0\n    // offset to -0.5 to 0.5\n    // expand to -1 to 1\n    transformedNormal *= ((vec3(lessMasks) * -1.0) + 0.5) * 2.0;\n\n    uint transformedNormalPacked = packSnorm4x8(vec4(transformedNormal, 0.0));\n\n    vec3 position = mat4x3(transform) * vec4(vertData.vX, vertData.vY, vertData.vZ, 1.0);\n    // Bake the entity pose into the position so the output Position attribute is camera-relative\n    // to match vanilla (fog).\n    position = (modelPose * vec4(position, 1.0)).xyz;\n\n    uint tintedColor = packUnorm4x8(unpackUnorm4x8(vertData.color) * unpackUnorm4x8(uint(tintColor)));\n\n    vertexDataOut[id] = VertexDataOut(\n        position.x,\n        position.y,\n        position.z,\n        tintedColor,\n        vertData.tX,\n        vertData.tY,\n        vertData.overlay,\n        uint(lightMap),\n        transformedNormalPacked\n    );\n}\n";
   }

   public static String method3() {
      return "#version 430\n\nstruct Transform {\n    // translate\n    float tX;\n    float tY;\n    float tZ;\n    // scale\n    float sX;\n    float sY;\n    float sZ;\n    // quaternion\n    float qX;\n    float qY;\n    float qZ;\n    float qW;\n};\n\nstruct VertexData {\n    float vX;\n    float vY;\n    float vZ;\n    uint normal;\n    int transformIndex;\n};\n\nlayout(std430, binding = 0) readonly buffer BaseVertices {\n    VertexData vertexData[];\n};\n\nlayout(std430, binding = 1) readonly buffer CurrentTransforms {\n    Transform currentTransforms[];\n};\n\nlayout(std430, binding = 2) writeonly buffer OutputVertices {\n    vec4 vertexDataOut[];\n};\n\nmat4 quaternionToMat(vec4 quat) {\n    float w2 = quat.w * quat.w;\n    float x2 = quat.x * quat.x;\n    float y2 = quat.y * quat.y;\n    float z2 = quat.z * quat.z;\n    float zw = quat.z * quat.w;\n    float dzw = zw + zw;\n    float xy = quat.x * quat.y;\n    float dxy = xy + xy;\n    float xz = quat.x * quat.z;\n    float dxz = xz + xz;\n    float yw = quat.y * quat.w;\n    float dyw = yw + yw;\n    float yz = quat.y * quat.z;\n    float dyz = yz + yz;\n    float xw = quat.x * quat.w;\n    float dxw = xw + xw;\n    vec4 col1 = vec4(w2 + x2 - z2 - y2, dxy + dzw, dxz - dyw, 0.0);\n    vec4 col2 = vec4(-dzw + dxy, y2 - z2 + w2 - x2, dyz + dxw, 0.0);\n    vec4 col3 = vec4(dyw + dxz, dyz - dxw, z2 - y2 - x2 + w2, 0.0);\n    return mat4(col1, col2, col3, vec4(0.0, 0.0, 0.0, 1.0));\n}\n\nlayout(local_size_x = 32) in;\n\nvoid main() {\n    uint id = gl_GlobalInvocationID.x;\n\n    if (id >= vertexData.length()) {\n        return;\n    }\n\n    VertexData vertData = vertexData[id];\n\n    int transformIndex = vertData.transformIndex;\n\n    Transform cur = currentTransforms[transformIndex];\n\n    vec4 curQuat = vec4(cur.qX, cur.qY, cur.qZ, cur.qW);\n\n    vec3 scale = vec3(cur.sX, cur.sY, cur.sZ);\n    vec3 translate = vec3(cur.tX, cur.tY, cur.tZ);\n\n    mat4 transform = quaternionToMat(curQuat);\n    transform[0].xyz *= scale.x;\n    transform[1].xyz *= scale.y;\n    transform[2].xyz *= scale.z;\n    transform[3].xyz += translate;\n\n    vec3 normal = unpackSnorm4x8(vertData.normal).xyz;\n\n    // rotate the normal before adding the scale and translate\n    vec3 transformedNormal = mat3(transform) * normal;\n\n    uint flags = (vertData.normal >> 24u) & 255u;\n    bvec3 negateFlags = bvec3(flags & 1u, flags & 2u, flags & 4u);\n    bvec3 lessMasks = lessThan(transformedNormal, vec3(0.0));\n\n    // vec3(lessMasks) * vec3(negateFlags) is basically a logical and\n    // negate the components so its either -1 or 0\n    // offset to -0.5 to 0.5\n    // expand to -1 to 1\n    transformedNormal *= (((vec3(lessMasks) * vec3(negateFlags)) * -1.0) + 0.5) * 2.0;\n\n    float transformedNormalPacked = uintBitsToFloat(packSnorm4x8(vec4(transformedNormal, 0.0)));\n\n    vec3 position = mat4x3(transform) * vec4(vertData.vX, vertData.vY, vertData.vZ, 1.0);\n\n    vertexDataOut[id] = vec4(position.xyz, transformedNormalPacked);\n}\n";
   }
}
